local nameTable = {}
local function buildItem(item)
    item.file = item.file or "war3mapImported\\treasurechest.mdl"
    item.Tip = item.Tip or ""
    item.Ubertip = item.Ubertip or ""
    item.goldcost = item.goldcost or 0
    if item.goldcost == 0 then
        item.sellable = 0
        item.pawnable = 0
    end
    if nameTable[item._id_force] ~= nil then
        stack("found duplicate id" .. item._id_force)
    end
    nameTable[item._id_force] = 1
    hslk_item(item)
    local itemsNeedTargetArt = {}
    itemsNeedTargetArt["双手剑"] = true
    itemsNeedTargetArt["双手锤"] = true
    itemsNeedTargetArt["双手斧"] = true
    itemsNeedTargetArt["法杖"] = true
    itemsNeedTargetArt["单手剑"] = true
    itemsNeedTargetArt["单手锤"] = true
    itemsNeedTargetArt["单手斧"] = true
    itemsNeedTargetArt["匕首"] = true
    itemsNeedTargetArt["拳套"] = true
    itemsNeedTargetArt["弓"] = true
    if item.equipment_type ~= nil and itemsNeedTargetArt[item.equipment_type] and item.TargetArt == nil then
        stack("Missing TargetArt for: " .. item.Name)
    end
    if item.hitem_type == "装备" and item.min_pinzhi >= 3 and item._jichuChaCao == nil then
        stack("Missing _jichuChaCao for: " .. item.Name)
    end
end

