                            damageSpeedType = CONST_DAMAGE_SPEED_TYPE.IMMEDIATE,
                            shanghainame = "寒冰箭"
                        })
                        hbuff.update(3, targetUnit, "严寒", false, function()
                                hattribute.set(targetUnit, 0, {
                                    attack_speed = "-5",
                                    move = "-20",
                                    skill_speed = "-5"
                                })
                            end, function()
                                hattribute.set(targetUnit, 0, {
                                    attack_speed = "+5",
                                    move = "+20",
                                    skill_speed = "+5"
                                })
                            end, "ReplaceableTextures\\fashi\\BTN_ASdQ2.blp",
                            "严寒：降低5%的攻击，技能和20的移动速度", 1, nil, nil, nil, nil,
                            HBUFF_UPDATE_MODE.OVERWRITE, true)
                    end
                })
            end
        end
    } },
    speed = 1.3,
    Description = "黑鳞所用的法杖，虽然是法杖但是由于是黑木制作而成所以比较沉重"
})

