                for _, unit in ipairs(units) do
                    hskillMoban.missile({
                        model = "Abilities\\Weapons\\RedDragonBreath\\RedDragonMissile.mdl",
                        scale = 1.0,
                        speed = 200,
                        height = 500,
                        hover = 150,
                        sourceUnit = triggerUnit,
                        targetX = hunit.x(unit),
                        targetY = hunit.y(unit),
                        onEnd = function(sourceUnit, targetUnit, x, y)
                            hskillMoban.radiusAOE(x, y, sourceUnit, 200, function(targetUnit)
                                hskill.damage({
                                    sourceUnit = sourceUnit,
                                    targetUnit = targetUnit,
                                    damage = hunit.getZhushuxing(sourceUnit) * 1.2,
                                    damageSrc = CONST_DAMAGE_SRC.skill,
                                    damageType = DAMAGE_TYPE.MOFA,
                                    triggerSkill = hslk.n2i("装备技能"),
                                    effect = "Abilities\\Weapons\\RedDragonBreath\\RedDragonMissile.mdl",
                                    damageSpeedType = CONST_DAMAGE_SPEED_TYPE.IMMEDIATE,
                                    damageElementType = { CONST_DAMAGE_ELEMENT_TYPE.FIRE },
                                    shanghainame = "狂暴火焰护符"
                                })
                            end)
                        end
                    })
                end
            end
        end
    } }
})

