buildItem({
    _parent = "stel",
    _id_force = "I095",
    Name = "阿而坎迪·兄弟会之剑",
    Art = "ReplaceableTextures\\zhuangbei\\INV_Sword_50.blp",
    -- Abilities
    abilList = equipment_skill._id,
    TargetArt = "war3mapImported\\weapon_ssj_024.mdx",
    -- Cooldown Group
    cooldownID = equipment_skill._id,
    _jichuChaCao = 1,
    equipment_type = "双手剑",
    hitem_type = "装备",
    equipped_attr = _attr({
        hit = "+3",
        gongji_baifenbi = "+5"
    }),
    equipped_skill = { {
        description =
        "反目：兄弟一出，再无兄弟。攻击有20%概率触发愤怒顺劈，对自身前方400码的敌人造成100%主属性加攻击力的金属物理伤害，cd15秒。当玩家周围300码内没有友军时，伤害提高100%。该技能同时会对受到影响的单位添加护甲消融状态，使其受到的所有物理伤害增加5%，持续5秒。",
        attr_type = CONST_EVENT.attack,
        attr = function(evtData)
            if math.random(1, 100) <= 20 and htime.setupAndCheckCoolDown(evtData.triggerUnit, "ALfanmu", 15) then
                local sourceUnit = evtData.triggerUnit
                local targetUnit = evtData.targetUnit
                local primary = hhero.getPrimary(sourceUnit)
                local primaryAttributeName = string.lower(primary) .. "_white"
                local primaryAttribute = hattr.getWithLimit(sourceUnit, nil, primaryAttributeName, 0)
                local attack = hattr.getWithLimit(sourceUnit, nil, "attack", 0)
                local damage = attack + primaryAttribute
                local units = hgroup.createByUnit(sourceUnit, 300, function(enumUnit)
                    local owner = hunit.getOwner(enumUnit)
                    if hplayer.isUser(owner) and hplayer.isPlaying(owner) and owner ~= hunit.getOwner(sourceUnit) then
                        return true
                    end
                end)
                if hgroup.isEmpty(units) then
                    damage = damage * 2
                end
                heffect.xyz("[zhuangbei]AL.mdx", hunit.x(sourceUnit), hunit.y(sourceUnit), hunit.z(sourceUnit), 0, 1,
                    1.3, 1.3, 1, 0, 0, hunit.getFacing(sourceUnit))
                hskillMoban.radiusAngleAOE(sourceUnit, 400, hunit.getFacing(sourceUnit), 180, function(target)
                    hskill.damage({
                        sourceUnit = sourceUnit,
                        targetUnit = target,
                        damage = damage,
                        damageSrc = CONST_DAMAGE_SRC.skill,
                        damageType = DAMAGE_TYPE.WULI,
                        triggerSkill = hslk.n2i("AI技能模版"),
                        damageElementType = { CONST_DAMAGE_ELEMENT_TYPE.METAL },
                        damageSpeedType = CONST_DAMAGE_SPEED_TYPE.IMMEDIATE,
                        shanghainame = "愤怒顺劈"
                    })
                    hbuff.update(5, target, "护甲消融", false, function()
                            hevent.register(target, CONST_EVENT.damagingCustomTarget, "护甲消融易伤",
                                function(evtData)
                                    if evtData.damageType ~= DAMAGE_TYPE.WULI then
                                        return
                                    end
                                    evtData.damage = evtData.damage * 1.05
                                end)
                        end, function()
                            hevent.unregister(target, CONST_EVENT.damagingCustomTarget, "护甲消融易伤")
                        end, "ReplaceableTextures\\zhuangbei\\INV_Sword_50.blp",
                        "护甲消融状态，在该状态下的目标在受到物理伤害时会额外受到5%的伤害",
                        nil, nil, nil, nil, nil, HBUFF_UPDATE_MODE.OVERWRITE, true)
                end)
            end
        end
    } },
    Description = "这把剑上刻着两个大写的字A.L.",
    min_pinzhi = 3,
    speed = 1.4
})

