    speed = 1.1,
    equipped_attr = _attr({
        zhushuxing_baifenbi = "+2",
        wu_chuan = "+3",
        fa_chuan = "+3"
    }),
    equipped_skill = { {
        description = function(itemLevel, pinzhi, nandu)
            return "攻击有7%的概率触发凤凰烈焰，对目标及其周围单位造成" .. (nandu * 30 + 40) .. "%主属性的火系魔法伤害，触发冷却10秒"
        end,
        attr_type = CONST_EVENT.attack,
        attr = function(evtData, dynamicItem)
            local sourceUnit = evtData.triggerUnit
            if math.random(1, 100) <= 7 and htime.setupAndCheckCoolDown(
                    sourceUnit, "凤凰烈焰", 10
                ) then
                local sourceUnit = evtData.triggerUnit
                local targetUnit = evtData.targetUnit
                local damage = hunit.getZhushuxing(sourceUnit) * (dynamicItem.nandu * 30 + 40) / 100
                heffect.xyz(
                    "Abilities\\Spells\\Other\\Incinerate\\FireLordDeathExplode.mdl",
                    hunit.x(targetUnit),
                    hunit.y(targetUnit),
                    hunit.z(targetUnit),
                    0,
                    1
                )
                hskillMoban.radiusAOE(
                    hunit.x(targetUnit),
                    hunit.y(targetUnit),
                    sourceUnit,
                    300,
                    function(filterUnit)
                        hskill.damage(
                            {
                                sourceUnit = sourceUnit,
                                targetUnit = filterUnit,
                                damage = damage,
                                damageSrc = CONST_DAMAGE_SRC.skill,
                                damageType = DAMAGE_TYPE.MOFA,
                                triggerSkill = hslk.n2i("装备技能"),
                                damageElementType = { CONST_DAMAGE_ELEMENT_TYPE.FIRE },
                                damageSpeedType = CONST_DAMAGE_SPEED_TYPE.IMMEDIATE,
                                shanghainame = "凤凰烈焰"
                            }
                        )
                    end
                    , false, true
                )
            end
        end
    } }
})

