    -- Cooldown Group
    cooldownID = equipment_skill._id,
    equipment_type = "双手斧",
    hitem_type = "装备",
    _weiyi = true,
    equipped_attr = _attr({
        master = "+30",
        wu_bao = "+3",
        gongji_baifenbi = "+3"
    }),
    equipped_skill = { {
        description = function(itemLevel, pinzhi, nandu)
            return "血腥风暴，你的近战攻击有7%几率制造一阵血腥风暴，每秒对周围300码敌人造成" .. (100 + nandu * 50) .. "%攻击力的金系流血伤害（物理周期性伤害），持续3秒，冷却时间60秒"
        end,
        attr_type = CONST_EVENT.attack,
        attr = function(evtData, dynamicItem)
            local sourceUnit = evtData.triggerUnit
            if math.random(1, 100) <= 7 and htime.setupAndCheckCoolDown(
                    sourceUnit, "血腥风暴", 60
                ) then
                local sourceUnit = evtData.triggerUnit
                local interval = 1
                local duration = 3
                local damage = hattribute.getWithLimit(sourceUnit, nil, "attack", 0) * (1 + dynamicItem.nandu * 0.5)
                heffect.attach("war3mapImported\\AZ_jingzi_jiansheng01_F1.mdx", sourceUnit, "origin", duration)
                htime.setInterval(
                    interval,
                    function(curTimer)
                        if curTimer.passedSec() > duration or hunit.isAlive(sourceUnit) == false then
                            curTimer.destroy()
                            return
                        end
                        hskillMoban.radiusAOE(
                            hunit.x(sourceUnit),
                            hunit.y(sourceUnit),
                            sourceUnit,
                            300,
                            function(filterUnit)
                                heffect.attach("war3mapImported\\AZ_hit1.mdx", filterUnit, "chest", 0)
                                hskill.damage(
                                    {
                                        sourceUnit = sourceUnit,
                                        targetUnit = filterUnit,
                                        damage = damage,
                                        damageSrc = CONST_DAMAGE_SRC.skill,
                                        damageType = DAMAGE_TYPE.WULI,
                                        triggerSkill = hslk.n2i("装备技能"),
                                        damageElementType = { CONST_DAMAGE_ELEMENT_TYPE.METAL },
                                        damageSpeedType = CONST_DAMAGE_SPEED_TYPE.DOT,
                                        shanghainame = "血腥风暴"
                                    }
                                )
                            end
                            , false, true
                        )
                    end
                )
            end
        end
