buildItem({
    _parent = "stel",
    _id_force = "I0D8",
    Name = "烈焰之击",
    Art = "ReplaceableTextures\\zhuangbei\\INV_Weapon_Shortblade_89.blp",
    -- Abilities
    abilList = equipment_skill._id,
    -- Cooldown Group
    cooldownID = equipment_skill._id,
    equipment_type = "法剑",
    hitem_type = "装备",
    _weiyi = true,
    equipped_attr = _attr({
        fa_chuan = "+6",
        fa_bao = "+3",
        skill_speed = "+5"
    }),
    equipped_skill = { {
        description = function(itemLevel, pinzhi, nandu)
            return "凤舞九天，法术伤害有" ..
                (nandu * 10) .. "%概率召唤一个凤凰魂环绕自己，增加100点智力，叠加" ..
                (nandu * 3) .. "层后再触发则会唤醒所有凤凰之魂，凤凰之魂冲向敌方单位并造成100%主属性的火系魔法伤害，同时玩家获得" ..
                (nandu * 300) .. "点智力增幅，持续10秒。凤凰之魂触发的最低间隔为1秒。"
        end,
        attr_type = CONST_EVENT.damage,
        attr = function(evtData, dynamicItem)
            if evtData.damageType ~= DAMAGE_TYPE.MOFA then
                return
            end
            local nandu = dynamicItem.nandu
            local rate = nandu * 10
            local maxStack = nandu * 3
            local maxAttr = nandu * 300
            if math.random(1, 100) <= rate and
                hbuff.hasBuff(evtData.triggerUnit, "凤舞九天") == false and
                htime.setupAndCheckCoolDown(evtData.triggerUnit, "凤凰之魂", 1) then
                local data = hcache.get(evtData.triggerUnit, "凤凰之魂")
                if data == nil then
                    data = {
                        count = 0,
                        effects = {}
                    }
                    hcache.set(evtData.triggerUnit, "凤凰之魂", data)
                end
                if data.count == maxStack then
                    heffect.xyz("AZ_F034.mdx", hunit.x(evtData.triggerUnit), hunit.y(evtData.triggerUnit),
                        hunit.z(evtData.triggerUnit), 0, 1)
                    hbuff.delete(evtData.triggerUnit, "凤凰之魂")
                    hbuff.update(10, evtData.triggerUnit, "凤舞九天", true, function()
                            hattribute.set(evtData.triggerUnit, 0, _attr({
                                int_white = "+" .. tostring(maxAttr)
                            }))
                        end, function()
                            hattribute.set(evtData.triggerUnit, 0, _attr({
                                int_white = "-" .. tostring(maxAttr)
                            }))
                        end, "ReplaceableTextures\\zhuangbei\\INV_Weapon_Shortblade_89.blp",
                        "触发凤舞九天，智力增加" .. maxAttr .. "点", 1, nil, nil, nil, nil, HBUFF_UPDATE_MODE.OVERWRITE,
                        true)
                    local targetX, targetY = hunit.x(evtData.targetUnit), hunit.y(evtData.targetUnit)
                    for i, effectAndTimer in ipairs(data.effects) do
                        htime.setTimeout(0.1 * i, function()
                            local effect = effectAndTimer[1]
                            hjapi.DzSetEffectVertexAlpha(effect, 255)
                            hjapi.EXEffectMatReset(effect)
                            local timer = effectAndTimer[2]
                            timer.destroy()
                            hskillMoban.missile({
                                effect = effect,
                                scale = 1.0,
                                speed = 500,
                                startX = hjapi.EXGetEffectX(effect),
                                startY = hjapi.EXGetEffectY(effect),
                                targetX = targetX,
                                targetY = targetY,
                                height = 2000,
                                hover = hjapi.Z(hunit.x(evtData.triggerUnit), hunit.y(evtData.triggerUnit)) + 50,
                                sourceUnit = evtData.triggerUnit,
                                --targetUnit = evtData.targetUnit,
                                --target_face_dis = 50,
                                onEnd = function(_, _, endX, endY)
                                    local primary = hhero.getPrimary(evtData.triggerUnit)
                                    local primaryAttributeName = string.lower(primary) .. "_white"
                                    local primaryAttribute = hattr.getWithLimit(evtData.triggerUnit, nil,
                                        primaryAttributeName, 0)
                                    hskillMoban.radiusAOE(
                                        endX, endY, evtData.triggerUnit, 300,
                                        function(targetUnit)
                                            hskill.damage({
                                                sourceUnit = evtData.triggerUnit,
                                                targetUnit = targetUnit,
                                                damage = primaryAttribute,
                                                damageSrc = CONST_DAMAGE_SRC.skill,
                                                damageType = DAMAGE_TYPE.MOFA,
                                                triggerSkill = hslk.n2i("装备技能"),
                                                damageElementType = { CONST_DAMAGE_ELEMENT_TYPE.FIRE },
                                                damageSpeedType = CONST_DAMAGE_SPEED_TYPE.IMMEDIATE,
                                                shanghainame = "凤舞九天"
                                            })
                                        end, false, true
                                    )
                                end
                            })
                        end)
                    end
                    hcache.free(evtData.triggerUnit, "凤凰之魂")
                else
                    data.count = data.count + 1
                    hbuff.addStackAttrBuff(
                        CONST_DAMAGE_SRC.skill,
                        evtData.triggerUnit,
                        "凤凰之魂",
                        _attr({ int_white = "+100" }),
                        60,
                        maxStack,
                        "ReplaceableTextures\\zhuangbei\\INV_Weapon_Shortblade_89.blp", "凤凰之魂|n每层增加100点智力", true
                    )
                    local e, timer = hskillMoban.wulihuanrao({
                        model = "Units\\Human\\Phoenix\\Phoenix.mdx",
                        animateScale = 1,
                        transparency = 0.3,
                        scale = 0.4,
                        number = 1,
                        dir = math.random(1, 2),
                        circleTime = 3,
                        z = math.random(1, 200),
                        dis = data.count * 30 + 50,
                        sourceUnit = evtData.triggerUnit
                    })
                    table.insert(data.effects, { e, timer })
                end
            end
        end
    }, {
        description = function(itemLevel, pinzhi, nandu)
            return "烈焰主宰，你造成的所有火焰伤害提高" .. (nandu * 2) .. "%"
        end,
        attr_type = CONST_EVENT.damagingCustomSource,
        attr = function(evtData, dynamicItem)
            local nandu = dynamicItem.nandu
            local damageElementType = evtData.damageElementType
            if damageElementType ~= nil and type(damageElementType) == "table" then
                for _, v in ipairs(damageElementType) do
                    if v == CONST_DAMAGE_ELEMENT_TYPE.HUNLUAN then
                        evtData.damage = evtData.damage * (1 + nandu * 0.02)
                        return
                    end
                end
            end
        end
    }, {
        description = function(itemLevel, pinzhi, nandu)
            return "点燃伤害提高" ..
                (2 + nandu * 4) ..
                "%，痛苦献祭伤害提高" ..
                (5 + nandu * 5) .. "%，献祭伤害提高" .. (10 + nandu * 30) .. "%，愤怒伤害提高" .. (1 + nandu * 3) .. "%"
        end,
        attr_type = CONST_EVENT.damagingCustomSource,
        attr = function(evtData, dynamicItem)
            local nandu = dynamicItem.nandu
            if evtData.triggerSkill == hslk.n2i("点燃") then
                evtData.damage = evtData.damage * (1 + 0.02 + nandu * 0.04)
            end
            if evtData.triggerSkill == hslk.n2i("痛苦献祭") then
                evtData.damage = evtData.damage * (1 + 0.05 + nandu * 0.05)
            end
            if evtData.triggerSkill == hslk.n2i("献祭") then
                evtData.damage = evtData.damage * (1 + 0.1 + nandu * 0.3)
            end
            if evtData.triggerSkill == hslk.n2i("愤怒") then
                evtData.damage = evtData.damage * (1 + 0.01 + nandu * 0.03)
            end
        end
    } },
    _jichuChaCao = 3,
    min_pinzhi = 4,
    speed = 1.2,
    TargetArt = "war3mapImported\\weapon_DSJ_17.mdx",
    Description = "火焰的君王。"
})

