buildItem({
    _parent = "stel",
    _id_force = "I0EO",
    Name = "暗月卡片：远征",
    Art = "ReplaceableTextures\\mingwen\\INV_Inscription_TarotLords.blp",
    -- Abilities
    abilList = equipment_skill._id,
    -- Cooldown Group
    cooldownID = equipment_skill._id,
    equipment_type = "饰品",
    _jichuChaCao = 1,
    hitem_type = "装备",
    min_pinzhi = 3,
    equipped_attr = _attr({
        fa_chuan = "+2",
        wu_chuan = "+2",
        hit = "+2"
    }),
    Description = "暗月教的圣物，具有强大的力量。",
    equipped_skill = { {
        description = function(itemLevel, pinzhi, nandu)
            local levelMulti = 1
            if itemLevel == 71 then
                levelMulti = 1.2
            elseif itemLevel == 72 then
                levelMulti = 1.4
            elseif itemLevel == 73 then
                levelMulti = 1.6
            end
            local shuxing = (nandu * 10 + 45) * levelMulti
            return "伤害有30%概率提升" .. shuxing ..
                "点主属性，可以叠加6层，持续15秒"
        end,
        attr_type = CONST_EVENT.damage,
        attr = function(evtData)
            local whichUnit = evtData.triggerUnit
            local dynamicItem = hplayer.dzCunDang[hunit.getOwner(whichUnit)].getEquipment(EQUIPMENT_SLOT_ID.shipin)
            local itemLevel = dynamicItem.level or 1
            local nandu = FUBEN_NANDU.PUTONG
            if dynamicItem ~= nil then
                nandu = dynamicItem.nandu
            end
            local levelMulti = 1
            if itemLevel == 71 then
                levelMulti = 1.2
            elseif itemLevel == 72 then
                levelMulti = 1.4
            elseif itemLevel == 73 then
                levelMulti = 1.6
            end
            local shuxing = (nandu * 10 + 45) * levelMulti
            if math.random(1, 100) <= 30 then
                hbuff.addStackAttrBuff(CONST_DAMAGE_SRC.skill, evtData.triggerUnit, "暗月卡片：远征", {
                        zhushuxing = "+" .. shuxing
                    }, 15, 6, "ReplaceableTextures\\mingwen\\INV_Inscription_TarotLords.blp",
                    "暗月卡片：远征|n每层增加" .. shuxing .. "点主属性", true)
            end
        end
    } }
})

