    hitem_type = "装备",
    _jichuChaCao = 1,
    min_pinzhi = 3,
    Description = "我能捏碎你的头。嗯，两次！",
    equipped_attr = _attr({
        fa_chuan = "+4",
        hit = "+3"
    }),
    equipped_skill = { {
        description = function(itemLevel, pinzhi, nandu)
            local life = 20 + nandu * 5
            return "使用获得" .. life .. "%的技能加速，持续12秒。冷却50秒。"
        end,
        attr_type = CONST_EVENT.skillEffect,
        cd = 50,
        attr = function(evtData)
            if evtData.triggerSkill == shipinjineng._id then
                local whichUnit = evtData.triggerUnit
                local dynamicItem = hplayer.dzCunDang[hunit.getOwner(whichUnit)].getEquipment(EQUIPMENT_SLOT_ID.shipin)
                local itemLevel = 1
                local pinzhi = 1
                local nandu = FUBEN_NANDU.PUTONG
                if dynamicItem ~= nil then
                    itemLevel = dynamicItem.level
                    pinzhi = dynamicItem.pinzhi
                    nandu = dynamicItem.nandu
                end
                local life = 20 + nandu * 5
                hbuff.update(
                    12,
                    whichUnit,
                    "古尔丹之颅",
                    true,
                    function()
                        hattr.set(whichUnit, 0, { skill_speed = "+" .. life })
                    end,
                    function()
                        hattr.set(whichUnit, 0, { skill_speed = "-" .. life })
                    end,
                    hslk.i2v(hslk.n2i("古尔丹之颅"), "Art"),
                    "古尔丹之颅|n获得" .. life .. "%的技能加速",
                    1,
                    nil,
                    nil,
                    nil,
                    nil,
                    HBUFF_UPDATE_MODE.OVERWRITE,
                    true
                )
            end
        end
    } }
})

