local function build_zhuangbei(id, name, art, equipment_type, equipped_attr, min_pinzhi, Description)
    buildItem({
        _parent = "stel",
        _id_force = id,
        Name = name,
        Art = art,
        -- Abilities
        abilList = equipment_skill._id,
        -- Cooldown Group
        cooldownID = equipment_skill._id,
        equipment_type = equipment_type,
        hitem_type = "装备",
        _jichuChaCao = 1,
        equipped_attr = equipped_attr,
        min_pinzhi = min_pinzhi,
        Description = Description
    })
end

