buildItem({
    _parent = "stel",
    _id_force = "I0HI",
    Name = "纯净的纳鲁薄片",
    Art = "ReplaceableTextures\\zhuangbei\\纯净的纳鲁薄片.blp",
    -- Abilities
    abilList = equipment_skill._id,
    -- Cooldown Group
    cooldownID = equipment_skill._id,
    equipment_type = "饰品",
    _jichuChaCao = 1,
    hitem_type = "装备",
    min_pinzhi = 3,
    equipped_attr = _attr({
        fa_chuan = "+4",
        wu_chuan = "+4",
        hit = "+4"
    }),
    Description = "纯净的纳鲁薄片，蕴含着强大的力量。",
    equipped_skill = { {
        description = function(itemLevel, pinzhi, nandu)
            local shuxing = (nandu * 5 + 5)
            return "造成任意伤害会提升" .. shuxing .. "点精通，该效果持续15秒，可以叠加6层"
        end,
        attr_type = CONST_EVENT.damage,
        attr = function(evtData)
            local whichUnit = evtData.triggerUnit
            local dynamicItem = hplayer.dzCunDang[hunit.getOwner(whichUnit)].getEquipment(EQUIPMENT_SLOT_ID.shipin)
            local itemLevel = dynamicItem.level or 1
            local nandu = FUBEN_NANDU.PUTONG
            if dynamicItem ~= nil then
                nandu = dynamicItem.nandu
            end
            local shuxing = (nandu * 5 + 5)

            hbuff.addStackAttrBuff(CONST_DAMAGE_SRC.skill, evtData.triggerUnit, "纯净的纳鲁薄片", {
                    master = "+" .. shuxing
                }, 15, 6, "ReplaceableTextures\\mingwen\\INV_Inscription_TarotLords.blp",
                "纯净的纳鲁薄片|n每层提升" .. shuxing .. "点精通，该效果持续15秒，可以叠加6层", true)
        end
    } }
})

